import {decorativeCount} from '../shared/presentation.js';
// Pooled impact meshes, shared material cache and deterministic local audio routing.
export function create3DEffects(runtime,{onEvent=()=>{},getPresentation=()=>({})}={}){const{B,scene}=runtime,pool=[],active=[],materials=new Map();function material(hex){if(!materials.has(hex)){const m=new B.StandardMaterial('fx-'+hex,scene);m.diffuseColor=B.Color3.FromHexString(hex);m.emissiveColor=m.diffuseColor.scale(.65);m.disableLighting=true;materials.set(hex,m);}return materials.get(hex);}
 function burst(p,color='#ffce61',n=7){n=decorativeCount(n,getPresentation());const max={low:40,medium:80,high:140}[runtime.quality]??40;for(let i=0;i<n&&active.length<max;i++){const m=pool.pop()||B.MeshBuilder.CreatePolyhedron('spark',{type:1,size:.08},scene);m.isPickable=false;m.material=material(color);m.setEnabled(true);m.position.set(p.x,p.y,p.z);active.push({m,life:.45,max:.45,vx:(Math.random()-.5)*3,vy:1+Math.random()*2,vz:(Math.random()-.5)*3});}}
 return{burst,event(e){const colors={heal:'#7cf6aa',block:'#98eaff',ice:'#92e7ff',fire:'#ff9b52',magic:'#c89dff',pulse:'#6ef3fa'};if(e.point)burst(e.point,colors[e.type]||colors[e.kind]||'#ffce61',e.type==='release'?3:7);onEvent(e);},update(dt){for(let i=active.length-1;i>=0;i--){const e=active[i];e.life-=dt;if(e.life<=0){e.m.setEnabled(false);pool.push(e.m);active.splice(i,1);continue;}e.vy-=7*dt;e.m.position.addInPlace(new B.Vector3(e.vx*dt,e.vy*dt,e.vz*dt));e.m.scaling.setAll(e.life/e.max);}},dispose(){for(const e of active)e.m.dispose();for(const m of pool)m.dispose();for(const m of materials.values())m.dispose();}};
}
